from collections import Counter

def prioritize_fields(schema, reference_rows, target_row):
    # Create a dictionary to store the frequency of each value for each field
    value_frequency = {}
    for row in reference_rows:
        for feature_id, value in row.items():
            if feature_id not in value_frequency:
                value_frequency[feature_id] = Counter()
            value_frequency[feature_id][value] += 1

