    suspicious_fields = []
    for feature_id, value in target_row.items():
        if feature_id in value_frequency:
            frequency = value_frequency[feature_id]
            # Calculate the frequency of the value in the target row
            target_frequency = frequency.get(value, 0)
            # Calculate the frequency of the value in the reference rows
            reference_frequency = sum(frequency.values()) - target_frequency
            # Calculate the suspiciousness score
